"-- ============================================\n-- THE CNPJOTO STREET — Migração: Loja Universal\n-- Execute DEPOIS do supabase-setup.sql original\n-- (Dashboard > SQL Editor > New Query)\n-- ============================================\n\n-- 1. NOVAS TABELAS\n-- ============================================\n\n-- Rastreamento de interesse prolongado (>60s olhando um produto)\nCREATE TABLE IF NOT EXISTS product_interest_tracking (\n  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n  customer_id UUID REFERENCES profiles(id) ON DELETE CASCADE,\n  product_id UUID REFERENCES products(id) ON DELETE CASCADE,\n  product_name TEXT,\n  customer_name TEXT,\n  viewing_seconds INTEGER NOT NULL DEFAULT 0,\n  notified_admin BOOLEAN DEFAULT false,\n  admin_action TEXT DEFAULT 'none' CHECK (admin_action IN ('none', 'discount_15', 'frete_gratis', 'cupom_personalizado', 'ignorado')),\n  admin_action_value DECIMAL(10,2) DEFAULT 0,\n  status TEXT DEFAULT 'ativo' CHECK (status IN ('ativo', 'acao_tomada', 'expirado')),\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW(),\n  UNIQUE(customer_id, product_id)\n);\n\n-- Cupons de boas-vindas (frete grátis automático no cadastro)\nCREATE TABLE IF NOT EXISTS welcome_coupons (\n  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n  customer_id UUID REFERENCES profiles(id) ON DELETE CASCADE,\n  code TEXT NOT NULL UNIQUE,\n  type TEXT DEFAULT 'frete_gratis' CHECK (type IN ('frete_gratis', 'desconto_percentual', 'desconto_fixo')),\n  value DECIMAL(10,2) DEFAULT 0,\n  used BOOLEAN DEFAULT false,\n  used_at TIMESTAMPTZ,\n  expires_at TIMESTAMPTZ DEFAULT (NOW() + INTERVAL '30 days'),\n  created_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- 2. RLS para novas tabelas\n-- ============================================\n\nALTER TABLE product_interest_tracking ENABLE ROW LEVEL SECURITY;\nALTER TABLE welcome_coupons ENABLE ROW LEVEL SECURITY;\n\n-- Interest Tracking: Cliente insere, admin lê tudo\nCREATE POLICY \"interest_insert\" ON product_interest_tracking FOR INSERT WITH CHEC
